import { useEffect, useMemo, useState } from 'react';
import { BriefcaseBusiness, CheckCircle2, MapPinned, Pencil, Plus, Trash2, UsersRound } from 'lucide-react';
import { apiRequest as api } from '../../lib/api';

const emptyBusiness = { name: '', category: '', description: '', city: '', state: '', address: '', latitude: '', longitude: '', priceFrom: '', capacity: '', contactName: '', contactPhone: '', contactEmail: '', photos: '', projects: '', amenities: '' };
const lines = value => value.split('\n').map(item => item.trim()).filter(Boolean);
const businessToForm = item => ({ name: item.name || '', category: item.category?._id || item.category || '', description: item.description || '', city: item.city || '', state: item.state || '', address: item.address || '', latitude: item.location?.latitude ?? '', longitude: item.location?.longitude ?? '', priceFrom: item.priceFrom ?? '', capacity: item.capacity ?? '', contactName: item.contact?.name || '', contactPhone: item.contact?.phone || '', contactEmail: item.contact?.email || '', photos: (item.photos || []).join('\n'), projects: (item.projects || []).map(project => `${project.title || ''}|${project.description || ''}|${project.photo || ''}`).join('\n'), amenities: (item.amenities || []).join('\n') });
const formToBusiness = form => ({ category: form.category, name: form.name, description: form.description, city: form.city, state: form.state, address: form.address, location: form.latitude || form.longitude ? { latitude: Number(form.latitude), longitude: Number(form.longitude) } : undefined, priceFrom: Number(form.priceFrom), capacity: form.capacity ? Number(form.capacity) : undefined, contact: { name: form.contactName, phone: form.contactPhone, email: form.contactEmail }, photos: lines(form.photos), projects: lines(form.projects).map(line => { const [title, description, photo] = line.split('|').map(value => value?.trim()); return { title, description, photo }; }), amenities: lines(form.amenities) });

export default function VendorDashboard({ user, updateUser }) {
  const [businesses, setBusinesses] = useState([]); const [enquiries, setEnquiries] = useState([]); const [categories, setCategories] = useState([]); const [categoriesError, setCategoriesError] = useState('');
  const [editing, setEditing] = useState(null); const [form, setForm] = useState(emptyBusiness); const [activeTab, setActiveTab] = useState('businesses'); const [notice, setNotice] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(true);
  const loadCategories = async () => { setCategoriesError(''); try { const data = await api('/categories'); setCategories(Array.isArray(data) ? data : data.items || []); } catch (cause) { setCategoriesError(cause.message); } };
  const load = async () => { setLoading(true); try { const [listingData, enquiryData] = await Promise.all([api('/vendor/listings'), api('/vendor/enquiries')]); setBusinesses(listingData.items); setEnquiries(enquiryData.items); } catch (cause) { setError(cause.message); } finally { setLoading(false); } };
  useEffect(() => { if (user) { load(); loadCategories(); } }, [user]);
  const openEditor = item => { setEditing(item?._id || 'new'); setForm(item ? businessToForm(item) : emptyBusiness); setNotice(''); setError(''); if (!categories.length) loadCategories(); };
  const save = async event => { event.preventDefault(); setError(''); try { const body = JSON.stringify(formToBusiness(form)); const result = await api(editing === 'new' ? '/vendor/listings' : `/vendor/listings/${editing}`, { method: editing === 'new' ? 'POST' : 'PUT', body }); if (result.isVendor) updateUser({ isVendor: true }); setNotice(editing === 'new' ? 'Your business is now listed.' : 'Business details updated.'); setEditing(null); await load(); } catch (cause) { setError(cause.message); } };
  const remove = async id => { if (!window.confirm('Remove this business from ShaadiScout? You can add it again later.')) return; try { await api(`/vendor/listings/${id}`, { method: 'DELETE' }); setNotice('Business removed from public listings.'); await load(); } catch (cause) { setError(cause.message); } };
  const updateStatus = async (id, status) => { try { await api(`/vendor/enquiries/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); setEnquiries(items => items.map(item => item._id === id ? { ...item, status } : item)); } catch (cause) { setError(cause.message); } };
  const newCount = useMemo(() => enquiries.filter(item => item.status === 'new').length, [enquiries]);
  if (!user) return <main className="vendor-landing"><BriefcaseBusiness size={44}/><p className="eyebrow">FOR WEDDING PROFESSIONALS</p><h1>Grow your wedding business with ShaadiScout.</h1><p>Register your business, showcase projects and receive callback requests from couples.</p><a className="vendor-primary" href="/auth">Sign in to get started</a></main>;
  return <main className="vendor-page"><section className="vendor-hero"><div><p className="eyebrow">VENDOR HUB</p><h1>{user.isVendor ? `Welcome back, ${user.name.split(' ')[0]}.` : 'List your wedding business.'}</h1><p>{user.isVendor ? 'Keep your profile fresh and turn new couple enquiries into conversations.' : 'Create your first listing to become a ShaadiScout vendor.'}</p></div><button className="vendor-primary" onClick={() => { setActiveTab('businesses'); openEditor(); }}><Plus size={18}/> Add business</button></section>
    <div className="vendor-tabs"><button className={activeTab === 'businesses' ? 'selected' : ''} onClick={() => setActiveTab('businesses')}><BriefcaseBusiness size={17}/> Businesses <span>{businesses.length}</span></button><button className={activeTab === 'enquiries' ? 'selected' : ''} onClick={() => setActiveTab('enquiries')}><UsersRound size={17}/> Callback requests {newCount > 0 && <span>{newCount}</span>}</button></div>
    {notice && <p className="vendor-notice"><CheckCircle2 size={17}/>{notice}</p>}{error && <p className="error vendor-error">{error}</p>}
    {loading ? <div className="empty">Loading your vendor hub…</div> : activeTab === 'businesses' ? <section className="business-grid">{businesses.map(item => <article className="business-card" key={item._id}><img src={item.photos?.[0] || 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=800&q=80'} alt=""/><div><p className="eyebrow">{item.category?.name || 'Wedding service'}</p><h2>{item.name}</h2><p><MapPinned size={15}/>{[item.city, item.state].filter(Boolean).join(', ')}</p><strong>From ₹{item.priceFrom.toLocaleString('en-IN')}</strong><div className="business-actions"><button onClick={() => openEditor(item)}><Pencil size={16}/> Edit</button><button className="delete" onClick={() => remove(item._id)}><Trash2 size={16}/> Remove</button></div></div></article>)}{!businesses.length && <div className="vendor-empty"><BriefcaseBusiness size={30}/><h2>Your storefront starts here.</h2><p>Add your business details, photos, location and past projects to publish a listing.</p><button className="vendor-primary" onClick={() => openEditor()}>Create first listing</button></div>}</section> : <section className="enquiry-list">{enquiries.map(item => <article className="enquiry" key={item._id}><div><span className={`status ${item.status}`}>{item.status}</span><h2>{item.name}</h2><p>{item.listing?.name} · {item.phone}</p>{item.message && <p className="enquiry-message">“{item.message}”</p>}<small>{new Date(item.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</small></div><label>Update status<select value={item.status} onChange={event => updateStatus(item._id, event.target.value)}><option value="new">New</option><option value="contacted">Contacted</option><option value="closed">Closed</option></select></label></article>)}{!enquiries.length && <div className="vendor-empty"><UsersRound size={30}/><h2>No callback requests yet.</h2><p>New requests from your public business pages will appear here.</p></div>}</section>}
    {editing && <BusinessEditor categories={categories} categoriesError={categoriesError} reloadCategories={loadCategories} form={form} setForm={setForm} isNew={editing === 'new'} onClose={() => setEditing(null)} onSave={save} />}
  </main>;
}

function BusinessEditor({ categories, categoriesError, reloadCategories, form, setForm, isNew, onClose, onSave }) { const change = (field, value) => setForm(current => ({ ...current, [field]: value })); const addPhoto = url => change('photos', [...lines(form.photos), url].join('\n')); const removePhoto = url => change('photos', lines(form.photos).filter(photo => photo !== url).join('\n')); const addProjectPhoto = url => change('projects', [...lines(form.projects), `Project photo||${url}`].join('\n')); const removeProjectPhoto = url => change('projects', lines(form.projects).filter(project => project.split('|')[2] !== url).join('\n')); return <div className="modal-backdrop"><div className="business-editor"><button className="close" onClick={onClose}>×</button><p className="eyebrow">{isNew ? 'VENDOR ONBOARDING' : 'EDIT BUSINESS'}</p><h2>{isNew ? 'Tell couples about your business.' : 'Keep your listing up to date.'}</h2><form onSubmit={onSave}><div className="form-grid"><label>Business name<input required value={form.name} onChange={e => change('name', e.target.value)} /></label><label>Category<select required value={form.category} onChange={e => change('category', e.target.value)} disabled={!categories.length}><option value="">{categories.length ? 'Choose a category' : 'Loading categories…'}</option>{categories.map(category => <option key={category._id} value={category._id}>{category.name}</option>)}</select>{categoriesError && <span className="field-error">Could not load categories. <button type="button" onClick={reloadCategories}>Try again</button></span>}</label><label>City<input required value={form.city} onChange={e => change('city', e.target.value)} /></label><label>State<input value={form.state} onChange={e => change('state', e.target.value)} /></label><label className="wide">Address<input value={form.address} onChange={e => change('address', e.target.value)} placeholder="Area, landmark or complete address" /></label><label>Map latitude<input type="number" step="any" value={form.latitude} onChange={e => change('latitude', e.target.value)} placeholder="e.g. 28.6139" /></label><label>Map longitude<input type="number" step="any" value={form.longitude} onChange={e => change('longitude', e.target.value)} placeholder="e.g. 77.2090" /></label><label>Starting price (₹)<input required min="0" type="number" value={form.priceFrom} onChange={e => change('priceFrom', e.target.value)} /></label><label>Guest capacity<input min="0" type="number" value={form.capacity} onChange={e => change('capacity', e.target.value)} /></label><label className="wide">About your business<textarea required value={form.description} onChange={e => change('description', e.target.value)} /></label><PhotoUpload label="Business photos" items={lines(form.photos)} onUploaded={addPhoto} onRemove={removePhoto} /><label className="wide">Projects (one per line: title | description)<textarea value={form.projects} onChange={e => change('projects', e.target.value)} /></label><PhotoUpload label="Project photos" items={lines(form.projects).filter(project => project.split('|')[2]).map(project => project.split('|')[2])} onUploaded={addProjectPhoto} onRemove={removeProjectPhoto} /><label className="wide">Amenities / services (one per line)<textarea value={form.amenities} onChange={e => change('amenities', e.target.value)} /></label><label>Contact person<input value={form.contactName} onChange={e => change('contactName', e.target.value)} /></label><label>Contact phone<input value={form.contactPhone} onChange={e => change('contactPhone', e.target.value)} /></label><label>Contact email<input type="email" value={form.contactEmail} onChange={e => change('contactEmail', e.target.value)} /></label></div><div className="editor-actions"><button type="button" onClick={onClose}>Cancel</button><button className="vendor-primary">{isNew ? 'Publish business' : 'Save changes'}</button></div></form></div></div> }

function PhotoUpload({ label, items, onUploaded, onRemove }) { const [uploading, setUploading] = useState(false); const [error, setError] = useState(''); const readFile = file => new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); const upload = async event => { const files = Array.from(event.target.files || []); event.target.value = ''; if (!files.length) return; const tooLarge = files.find(file => file.size > 6 * 1024 * 1024); if (tooLarge) return setError(`${tooLarge.name} is over the 6 MB limit.`); setUploading(true); setError(''); try { for (const file of files) { if (!file.type.startsWith('image/')) throw new Error('Please select image files only.'); const image = await readFile(file); const result = await api('/vendor/uploads', { method: 'POST', body: JSON.stringify({ image }) }); onUploaded(result.url); } } catch (cause) { setError(cause.message); } finally { setUploading(false); } }; return <div className="wide photo-upload"><span>{label}</span><label className="upload-button"><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple onChange={upload} disabled={uploading} />{uploading ? 'Uploading to Cloudinary…' : 'Upload from device'}</label>{error && <small className="field-error">{error}</small>}{!!items.length && <div className="uploaded-images">{items.map((url, index) => <div key={`${url}-${index}`}><img src={url} alt="Uploaded preview"/><button type="button" onClick={() => onRemove(url)} aria-label="Remove image">×</button></div>)}</div>}</div> }
